import unittest
from candidate import separate_paren_groups

class TestSeparateParenGroups(unittest.TestCase):
    def test_normal_case(self):
        self.assertListEqual(separate_paren_groups('( ) (( )) (( )( ))'), ['()', '(())', '(()())'])

    def test_empty_string(self):
        self.assertListEqual(separate_paren_groups(''), [])

    def test_single_group(self):
        self.assertListEqual(separate_paren_groups('(a)'), ['(a)'])

    def test_multiple_groups(self):
        self.assertListEqual(separate_paren_groups('(a) (b) (c)'), ['(a)', '(b)', '(c)'])

    def test_nested_groups(self):
        self.assertListEqual(separate_paren_groups('((a))'), ['(a)'])

    def test_mixed_nested_groups(self):
        self.assertListEqual(separate_paren_groups('(a) ((b)) (c)'), ['(a)', '(b)', '(c)'])

    def test_unbalanced_groups(self):
        self.assertRaises(ValueError, separate_paren_groups, '(a) (b)(')

    def test_only_open_brackets(self):
        self.assertRaises(ValueError, separate_paren_groups, '(a) (b(')

    def test_only_closed_brackets(self):
        self.assertRaises(ValueError, separate_paren_groups, ')(a) (b)(')

    def test_non_string_input(self):
        self.assertRaises(TypeError, separate_paren_groups, 1)

if __name__ == '__main__':
    unittest.main()
